r_d = read_pdf(46,47)
pdf_pages = {}
for r in (r_a, r_b, r_c, r_d):
    for p in r.get('pages', []):
        pdf_pages[p['page']] = p['text']
print(sorted(pdf_pages))
def win(page, kw, before=250, after=400):
    t = pdf_pages.get(page,'')
    for m in re.finditer(re.escape(kw), t):
        s = max(0, m.start()-before); e = min(len(t), m.end()+after)
        print('---', page, kw, '---')
        print(t[s:e].replace('\n',' '))
for kw in ['snowball','Scholar','categories of','majority']:
    for pg in (4,5,10,11,12,13):
        if pg in pdf_pages: win(pg, kw)

