import re as _re
def norm(s):
    return _re.sub(r'\s+', ' ', s)
def win(p, key, before=200, after=500, idx=0):
    n = norm(page(p))
    i = -1
    for _ in range(idx+1):
        i = n.find(key, i+1)
        if i == -1:
            return f'[{p}] NOTFOUND {key!r}'
    return f'[{p}] ...{n[max(0,i-before):i+after]}...'
print(win(13, 'breadth-first', 300, 200))
print(win(4, 'interacting', 600, 300))
