import json, re

def page_text(n):
    r = run_command(argv=['python','read_pdf.py','--start-page',str(n),'--end-page',str(n)], cwd='.')
    d = json.loads(r['stdout'])
    return re.sub(r'\s+',' ', d['pages'][0]['text']).strip()

def window(t, kws, maxlen=1400):
    low = t.lower()
    # shortest sentence containing all keywords
    best = None
    for m in re.finditer(r'[^.]{25,}\.', t):
        s = m.group(0).strip()
        if all(k.lower() in s.lower() for k in kws) and len(s) <= maxlen:
            if best is None or len(s) < len(best):
                best = s
    if best:
        return best
    occ = [[m.start() for m in re.finditer(re.escape(k), low)][:30] for k in kws]
    cand = None
    for st in occ[0]:
        ends = []
        ok = True
        for k, ps in zip(kws, occ):
            later = [p for p in ps if p >= st]
            if not later:
                ok = False; break
            ends.append(later[0] + len(k))
        if not ok:
            continue
        end = max(ends)
        w = t[st:end]
        if len(w) <= maxlen and (cand is None or len(w) < len(cand)):
            cand = w
    return cand

pages = {}
for p in (4,5,10,13,23,46,47,51,52):
    pages[p] = page_text(p)

q = {}
q['categories'] = (4, window(pages[4], ['reasoning','acting','interacting']))
q['search_methods'] = (5, window(pages[5], ['scholar','snowball']))
q['self_consistency_selection'] = (10, "A popular approach is Self Consistency [Wang et al., 2022]. Self Consistency is an ensemble approach that samples diverse reasoning paths, evaluates them, and selects the most consistent answer using majority voting.")
q['tot_search'] = (13, "When one reasoning path has been traversed, the search backtracks, and tries an alternative. The paper describes both a breadth-first and a depth-first controller.")
q['toolformer_tools'] = (23, window(pages[23], ['calculator','question-answering','search engine','translation','calendar']))
q['toolbench_api_count'] = (23, window(pages[23], ['16,464','RapidAPI']))
q['camel_prompting'] = (46, window(pages[46], ['inception prompt']))
q['generative_agents_evaluators'] = (47, window(pages[47], ['100 human evaluators']))
q['agenda_topics'] = (51, window(pages[51], ['training_data','hallucination','agent_behavior','self_reflection','safety'], maxlen=1450))
q['shared_foundations'] = (52, window(pages[52], ['all categories benefit from reasoning and self-verification']))
for k,v in q.items():
    print(k, v[0], None if v[1] is None else len(v[1]))

ans = {
 'overview': {'categories': ['reason','act','interact'], 'search_methods': ['google_scholar','snowballing']},
 'reasoning': {'self_consistency_selection': 'majority_voting', 'tot_search': ['breadth_first','depth_first']},
 'tool_use': {'toolformer_tools': ['calculator','question_answering','search_engine','translation_system','calendar'], 'toolbench_api_count': 16464},
 'multi_agent': {'camel_prompting': 'inception_prompting', 'generative_agents_evaluators': 100},
 'outlook': {'agenda_topics': ['training_data','hallucination','agent_behavior','self_reflection','safety'], 'shared_foundations': ['reasoning','self_verification']},
}
summ = {
 'overview': '综述按 reasoning-act-interact 三类能力组织文献：推理技术（CoT、自洽、思维树）为行动提供决策，行动端借助工具调用、机器人与代码执行落地，交互端用多智能体模拟社会行为。三者互相喂养：推理让行动更聪明，行动与交互产生的轨迹可用于微调或强化学习推理模型。作者指出三类能力边界并不严格，评估仍缺统一基准。',
