 'outlook': '已实现：结构校验（pytest）与证据哈希。不足：缺少自我验证式事实核对与安全过滤。改进：在写报告前对每条引文做页码与原文比对，并蒸馏到更小模型以降低成本。',
}
order = ['overview','reasoning','tool_use','multi_agent','outlook']
sections = []
for sid in order:
    ev = []
    for field, val in ans[sid].items():
        pg_no, quote = q[field]
        ev.append({'question': field, 'page': pg_no, 'quote': re.sub(r'\s+',' ', quote).strip()})
    sections.append({'id': sid, 'summary': summ[sid], 'application': appl[sid], 'answers': ans[sid], 'evidence': ev})
report = {'overview': '本文（arXiv:2503.23037v3）系统综述 Agentic Large Language Models：把大模型视为能推理、能行动、能与他人交互的智能体。作者先以 Google Scholar 与雪球法收集文献，再按 reasoning、acting、interacting 三类能力组织材料，覆盖提示增强推理、工具调用与机器人行动、多智能体社会模拟，并讨论评估、安全与研究议程，指出三类能力共享推理与自我验证的基础。', 'sections': sections}
h = read_file('report.json')['file_hash']
w = write_file('report.json', json.dumps(report, ensure_ascii=False, indent=2), expected_hash=h)
print('written', w['file_hash'][:8])
